/**
 * OCCASION CATALOGUE
 * ------------------------------------------------------------------
 * To add a new festival / occasion:
 *   1. Add an entry below (unique `id`, English text, category, theme…).
 *   2. (Optional) add translations in client/src/i18n/locales/<lang>.json
 *      under "occ" → "<id>" → { name, headline, message }.
 *      Missing translations automatically fall back to English.
 * No other code changes are needed — search, filters, forms and the
 * greeting renderer pick up new entries automatically.
 */

export type Category =
  | "occasion"
  | "festival"
  | "regional"
  | "national"
  | "important"
  | "hindu"
  | "islamic"
  | "christian"
  | "sikh"
  | "buddhist"
  | "jain"
  | "parsi"
  | "harvest";

/** Which input fields the form shows (see data/fields.ts) */
export type FieldSet =
  | "festival" // sender name, company, logo, phone, message
  | "birthday"
  | "anniversary"
  | "wedding"
  | "business" // wishing another business / person on a business milestone
  | "work" // work anniversary: colleague / employee + years
  | "personal" // recipient required
  | "general"; // recipient optional

export type ThemeKey =
  | "diwali"
  | "holi"
  | "newyear"
  | "birthday"
  | "anniversary"
  | "harvest"
  | "devotional"
  | "eid"
  | "christmas"
  | "national"
  | "floral"
  | "royal"
  | "toran"
  | "lotus";

export interface Occasion {
  id: string;
  name: string;
  headline: string;
  message: string;
  category: Category;
  fieldSet: FieldSet;
  theme: ThemeKey;
  /** Approximate Gregorian months (1-12) — used for "Coming up" */
  months: number[];
  /** States / regions where it's especially celebrated ("All India" if pan-India) */
  regions: string[];
  /** Extra search terms (English / transliterated) */
  keywords?: string[];
  /** Alternative/alias names are searchable but are rendered as one clean occasion. */
  alternativeNames?: string[];
  /** Fixed Gregorian date when applicable, e.g. "26 January". */
  date?: string;
  /** Optional list of internal language codes for future template targeting. */
  supportedLanguages?: string[];
  popular?: boolean;
}

